const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    passportReadable: true,
    extractedFullName: item.applicantName,
    extractedNationality: item.nationality,
    extractedPassportNumber: 'Unavailable',
    extractedDOB: 'Unknown',
    extractedExpiryDate: 'Unknown',
    monthsUntilExpiry: 12,
    consistencyIssues: [],
    extractionNotes: 'Auto-passed: could not parse AI passport extraction output, trusting self-reported nationality',
    extractionScore: 5
  };
}
return { json: { ...item, ...parsed } };

const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    visaRequired: true,
    visaCategory: 'Unknown',
    recommendedVisaType: 'Consult destination embassy or consulate',
    maxStayAllowedDays: null,
    estimatedProcessingTime: 'Unknown',
    eligibilityRisks: [],
    officialSourceRecommendation: 'Verify current requirements with the destination country embassy or consulate before applying.',
    reasoning: 'Auto-flagged: could not parse AI visa rules output, defaulting to a cautious consult-embassy recommendation.',
    confidence: 30
  };
}
return { json: { ...item, ...parsed } };

const item = $input.item.json;

const baseChecklist = [
  'Valid passport with at least 6 months validity remaining beyond the intended stay',
  '2 recent passport-size photographs meeting destination photo specifications',
  'Completed visa application form (paper or online, as applicable)',
  'Proof of onward or return travel (flight itinerary/reservation)',
  'Proof of accommodation for the full stay (hotel booking or invitation letter)',
  'Proof of sufficient financial means (bank statements, last 3-6 months)',
  'Travel/medical insurance covering the destination and travel dates'
];

const purposeChecklists = {
  'Tourism': [],
  'Business': ['Invitation letter from the host company or business partner', 'Company letter confirming purpose and duration of trip'],
  'Study': ['Acceptance/enrollment letter from the educational institution', 'Proof of tuition payment or scholarship', 'Proof of financial sponsorship for the duration of study'],
  'Work': ['Valid work permit or employment authorization', 'Employment contract or offer letter', 'Employer sponsorship letter'],
  'Family Visit': ['Invitation letter from the host in the destination country', 'Proof of relationship to the host (if applicable)', "Host's proof of residency/status in the destination country"],
  'Transit': ['Onward ticket to final destination', 'Visa for final destination country, if required']
};

const purpose = item.travelPurpose || 'Tourism';
const purposeItems = purposeChecklists[purpose] || [];

const riskItems = (item.eligibilityRisks || []).map(r => `Address flagged risk: ${r}`);

const checklist = [...baseChecklist, ...purposeItems, ...riskItems];

return {
  json: {
    ...item,
    documentChecklist: checklist,
    checklistGeneratedAt: new Date().toISOString()
  }
};

const item = $input.item.json;

const checklistHtml = (item.documentChecklist || [])
  .map(c => `<li>${c}</li>`)
  .join('');

const risksHtml = (item.eligibilityRisks || []).length
  ? `<h3>Eligibility Risks to Address</h3><ul>${item.eligibilityRisks.map(r => `<li>${r}</li>`).join('')}</ul>`
  : '';

const html = `
<html>
<head><meta charset="utf-8"><style>
body { font-family: Arial, sans-serif; padding: 32px; color: #1a1a1a; }
h1 { font-size: 20px; margin-bottom: 4px; }
h2 { font-size: 16px; margin-top: 24px; }
p { font-size: 13px; line-height: 1.5; }
ul { font-size: 13px; line-height: 1.6; }
.meta { color: #555; font-size: 12px; margin-bottom: 16px; }
.disclaimer { margin-top: 24px; padding: 12px; background: #f5f5f5; font-size: 11px; color: #444; }
</style></head>
<body>
<h1>Visa Eligibility Assessment &amp; Document Checklist</h1>
<div class="meta">Application ID: ${item.applicationId} &middot; Generated: ${item.checklistGeneratedAt}</div>
<p><strong>Applicant:</strong> ${item.applicantName}<br/>
<strong>Nationality:</strong> ${item.extractedNationality}<br/>
<strong>Destination:</strong> ${item.destinationCountry}<br/>
<strong>Purpose of Travel:</strong> ${item.travelPurpose}<br/>
<strong>Intended Stay:</strong> ${item.intendedStayDays} days, arriving ${item.intendedArrivalDate}</p>

<h2>Visa Assessment</h2>
<p><strong>Visa Required:</strong> ${item.visaRequired ? 'Yes' : 'No'}<br/>
<strong>Visa Category:</strong> ${item.visaCategory}<br/>
<strong>Recommended Visa Type:</strong> ${item.recommendedVisaType}<br/>
<strong>Estimated Processing Time:</strong> ${item.estimatedProcessingTime}<br/>
<strong>Confidence:</strong> ${item.confidence}%</p>
<p>${item.reasoning}</p>

${risksHtml}

<h2>Document Checklist</h2>
<ul>${checklistHtml}</ul>

<div class="disclaimer">This assessment is generated to help you prepare, and is not an official visa decision. Visa policies change frequently. ${item.officialSourceRecommendation}</div>
</body>
</html>
`;

return { json: { ...item, checklistHtml: html } };

const item = $input.item.json;
const decidedAt = new Date().toISOString();

return {
  json: {
    ...item,
    decidedAt,
    applicationSummaryRow: [
      item.applicationId || 'N/A',
      item.applicantName || '',
      item.applicantEmail || '',
      item.destinationCountry || '',
      item.travelPurpose || '',
      item.extractedNationality || '',
      item.visaRequired ? 'Yes' : 'No',
      item.visaCategory || '',
      item.recommendedVisaType || '',
      item.confidence || 0,
      decidedAt
    ]
  }
};

